namespace Kaitai\Struct\Tests;

class ExprInt64ContextsTest extends TestCase {
    public function testExprInt64Contexts() {
        $r = ExprInt64Contexts::fromFile(self::SRC_DIR_PATH . '/expr_int64_contexts.bin');
        $this->assertSame(4294967328, $r->ofsEnd());
        $this->assertSame(4294967296, $r->ofsStart());
        $this->assertSame(5, $r->lenStr());
        $this->assertSame(3, $r->numItems());
        $this->assertSame(1, $r->idx());
        $this->assertSame(3, count($r->items()));
        $this->assertSame("hello", $r->strVal());
        $this->assertSame(17, $r->child()->val());
        $this->assertSame(18, $r->child()->valPlusOne());
        $this->assertSame(127, $r->byteAtOfs());
        $this->assertSame(34, $r->itemAtIdx());
        $this->assertSame("el", $r->substr());
        $this->assertEquals($r->mulFloat(), 7.5, '', 1e-6);
        $this->assertEquals($r->mulFloatCast(), 2.5, '', 1e-6);
        $this->assertEquals($r->mulFloatTernary(), 10.0, '', 1e-6);
    }
}
